#!/usr/bin/env python3
"""Generate the fixed128K/Q4 smoke and customer Model entry points."""

import argparse
import importlib.util
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BATCH_SCRIPT = ROOT / "scripts/run_split_core_cases.py"


def matrix():
    spec = importlib.util.spec_from_file_location("split_core_cases", BATCH_SCRIPT)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def entry(suite):
    return r"""#!/usr/bin/env bash
# Generated by scripts/generate_split_core_sim.py; edit the generator.
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
KVIP_ROOT="${KVIP_ROOT:-$(cd -- "$SCRIPT_DIR/../.." && pwd)}"
for arg in "$@"; do
    case "$arg" in
        --backend|--backend=*|--suite|--suite=*)
            printf '%s\n' 'Generated entry fixes Model backend and suite; use the Python CLI for native' >&2
            exit 2 ;;
    esac
done
KVIP_ACTION="${KVIP_ACTION:-run}"
KVIP_PYTHON="${KVIP_PYTHON:-python3}"
KVIP_BUDGET="${KVIP_BUDGET:-28/56}"
KVIP_TOPK_SHARDS="${KVIP_TOPK_SHARDS:-1}"
KVIP_HEADS="${KVIP_HEADS:-32}"
KVIP_OUTPUT="${KVIP_OUTPUT:-$KVIP_ROOT/tests/results/split-__SUITE__-$(date -u +%Y%m%dT%H%M%S)-$$}"
if [[ -n "${KVIP_SIM_LEASE_FILE:-}" ]]; then
    set -- --lease-file "$KVIP_SIM_LEASE_FILE" "$@"
fi
if [[ "$KVIP_ACTION" == run ]]; then
    ASCEND_HOME_PATH="${ASCEND_HOME_PATH:-/usr/local/Ascend/cann}"
    if [[ -z "${KVIP_CANN_ARCH:-}" ]]; then
        case "$(uname -m)" in
            aarch64|arm64) KVIP_CANN_ARCH=aarch64-linux ;;
            x86_64) KVIP_CANN_ARCH=x86_64-linux ;;
            *) printf '%s\n' 'Set KVIP_CANN_ARCH for this CANN installation' >&2; exit 2 ;;
        esac
    fi
    model_lib="$ASCEND_HOME_PATH/$KVIP_CANN_ARCH/simulator/dav_3510/lib"
    if [[ ! -f "$model_lib/libruntime_camodel.so" ]]; then
        printf '%s\n' "Missing CANN Model runtime: $model_lib/libruntime_camodel.so" >&2
        exit 2
    fi
    if [[ -z "${KVIP_MODEL_DRIVER:-}" ]]; then
        KVIP_BUILD_DIR="${KVIP_BUILD_DIR:-$KVIP_ROOT/build/split-topk}"
        cmake -S "$KVIP_ROOT/csrc/operators/split_topk" -B "$KVIP_BUILD_DIR" \
            -DRUN_MODE=sim "-DSOC_VERSION=${KVIP_SOC:-Ascend950PR_9599}" \
            "-DASCEND_CANN_PACKAGE_PATH=$ASCEND_HOME_PATH"
        cmake --build "$KVIP_BUILD_DIR" --target topk_sim -j "${KVIP_BUILD_JOBS:-2}"
        KVIP_MODEL_DRIVER="$KVIP_BUILD_DIR/topk_sim"
    fi
    export LD_LIBRARY_PATH="$model_lib:$ASCEND_HOME_PATH/$KVIP_CANN_ARCH/lib64:$ASCEND_HOME_PATH/$KVIP_CANN_ARCH/devlib${LD_LIBRARY_PATH:+:$LD_LIBRARY_PATH}"
    export LD_PRELOAD="$model_lib/libruntime_camodel.so${LD_PRELOAD:+:$LD_PRELOAD}"
    set -- --model-driver "$KVIP_MODEL_DRIVER" "$@"
fi
exec "$KVIP_PYTHON" "$KVIP_ROOT/scripts/run_split_core_cases.py" "$KVIP_ACTION" \
    --backend model --suite __SUITE__ --group all --budget "$KVIP_BUDGET" \
    --shards "$KVIP_TOPK_SHARDS" --heads "$KVIP_HEADS" --output "$KVIP_OUTPUT" \
    "$@"
""".replace("__SUITE__", suite)


def compare_entry():
    return r"""#!/usr/bin/env bash
# Generated; serial 42-case runs for T1/T4/T8 at V56/V64 (252 conditions).
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
KVIP_ROOT="${KVIP_ROOT:-$(cd -- "$SCRIPT_DIR/../.." && pwd)}"
for arg in "$@"; do
    case "$arg" in
        --backend|--backend=*|--suite|--suite=*|--shards|--shards=*|--budget|--budget=*|--output|--output=*)
            printf '%s\n' 'compare.sh fixes backend/suite/T/budget/output; configure root with KVIP_OUTPUT' >&2
            exit 2 ;;
    esac
done
comparison_root="${KVIP_OUTPUT:-$KVIP_ROOT/tests/results/split-compare-$(date -u +%Y%m%dT%H%M%S)-$$}"
failed=0
for budget in 28/56 32/64; do
    for shards in 1 4 8; do
        tag="t${shards}-c${budget%/*}-v${budget#*/}"
        if ! KVIP_OUTPUT="$comparison_root/$tag" KVIP_BUDGET="$budget" \
             KVIP_TOPK_SHARDS="$shards" bash "$SCRIPT_DIR/customer.sh" "$@"; then
            failed=1
        fi
    done
done
exit "$failed"
"""


def generate(output):
    module = matrix()
    cases = list(module.cases())
    assert len(cases) == 42
    output.mkdir(parents=True, exist_ok=True)
    manifest = dict(
        matrix_version=module.MATRIX_VERSION,
        history=131072,
        queries_per_request=4,
        batches=list(module.BATCHES),
        miss_percent=list(module.MISSES),
        suites={"smoke": 42, "customer": 42},
        group_counts={g: len(list(module.cases(g))) for g in ("small", "medium", "large")},
        default_topk_shards=1,
        default_budget="28/56",
        comparison_conditions=252,
        scope="AIV-only TopK Model; no QK/Fetch/Service or production P32/T8",
        cases=cases,
    )
    (output / "cases.json").write_text(json.dumps(manifest, indent=2) + "\n")
    for suite in ("smoke", "customer"):
        p = output / f"{suite}.sh"
        p.write_text(entry(suite))
        p.chmod(0o755)
    p = output / "compare.sh"
    p.write_text(compare_entry())
    p.chmod(0o755)
    return manifest


def main():
    parser = argparse.ArgumentParser(__doc__, allow_abbrev=False)
    parser.add_argument("--output", type=Path, default=ROOT / "scripts/split_core_sim")
    args = parser.parse_args()
    manifest = generate(args.output)
    print(json.dumps(dict(status="generated", cases=len(manifest["cases"]), output=str(args.output))))


if __name__ == "__main__":
    main()
